use kimo_core::{commands::{Session,dispatch},render,color::pipeline::export_high};
use serde_json::json;
use std::process::Command;
fn fixture(w:u32,h:u32)->Session{let mut s=Session::new();dispatch(&mut s,"project_set",&json!({"width":w,"height":h,"fps":25})).unwrap();let tr=dispatch(&mut s,"add_track",&json!({})).unwrap()["track_id"].clone();dispatch(&mut s,"add_clip",&json!({"track_id":tr,"source_type":"solid","color":[1.,0.2,13./255.],"start":0,"duration":0.08})).unwrap();s}
#[test]fn ordinary_video_tags_and_709_swatch(){for(w,h)in[(32,32),(1280,720)]{let s=fixture(w,h);let path=std::env::temp_dir().join(format!("kimo-delivery-{}-{w}.mp4",std::process::id()));render::export(&s.project,path.to_str().unwrap(),0).unwrap();let probe=Command::new("ffprobe").args(["-v","error","-select_streams","v:0","-show_entries","stream=color_range,color_space,color_transfer,color_primaries","-of","json",path.to_str().unwrap()]).output().unwrap();assert!(probe.status.success());let p:serde_json::Value=serde_json::from_slice(&probe.stdout).unwrap();assert_eq!(p["streams"][0],json!({"color_range":"tv","color_space":"bt709","color_transfer":"iec61966-2-1","color_primaries":"bt709"}));let raw=Command::new("ffmpeg").args(["-v","error","-i",path.to_str().unwrap(),"-frames:v","1","-f","rawvideo","-pix_fmt","yuv420p","-"]).output().unwrap();assert!(raw.status.success());let n=(w*h)as usize;assert_eq!(raw.stdout.len(),n*3/2);let(y,u,v)=(raw.stdout[n/2]as f64,raw.stdout[n+n/8]as f64,raw.stdout[n+n/4+n/8]as f64);assert_eq!([y,u,v],[95.,91.,219.]);let yy=(y-16.)*255./219.;let cb=(u-128.)*255./224.;let cr=(v-128.)*255./224.;let rgb=[yy+1.5748*cr,yy-(0.0722*1.8556/0.7152)*cb-(0.2126*1.5748/0.7152)*cr,yy+1.8556*cb];for(a,b)in rgb.into_iter().zip([255.,51.,13.]){assert!((a.clamp(0.,255.)-b).abs()<2.)}let trace=Command::new("ffmpeg").args(["-v","verbose","-i",path.to_str().unwrap(),"-c:v","copy","-bsf:v","trace_headers","-f","null","-"]).output().unwrap();assert!(trace.status.success());let text=String::from_utf8_lossy(&trace.stderr);for(key,value)in[("video_signal_type_present_flag","1"),("video_full_range_flag","0"),("colour_description_present_flag","1"),("colour_primaries","1"),("transfer_characteristics","13"),("matrix_coefficients","1")]{assert!(text.lines().any(|l|l.contains(key)&&l.ends_with(&format!("= {value}"))),"missing {key}");}std::fs::remove_file(path).unwrap();}}
#[test]fn hlg_unsupported_gamuts_fail_before_file(){let mut s=fixture(32,32);let path=std::env::temp_dir().join(format!("kimo-hlg-reject-{}.mp4",std::process::id()));for g in[0,2,3,4,5,6,7]{s.project.color_pipeline.enabled=true;s.project.color_pipeline.output_transfer=7;s.project.color_pipeline.output_gamut=g;assert!(export_high(&s.project,path.to_str().unwrap(),"hevc10",18).unwrap_err().contains("HLG export requires Rec2020"));assert!(!path.exists());}}
